diff:
--- a/billing/pricing.tsx
+++ b/billing/pricing.tsx
@@
-  const price = plan.monthly;
+  const [annual, setAnnual] = useState(false);
+  const price = annual ? plan.monthly * 12 * 0.8 : plan.monthly;
+  return (
+    <>
+      <Toggle value={annual} onChange={setAnnual} label="Annual billing" />
+      <PriceTag amount={price} period={annual ? 'yr' : 'mo'} />
+    </>
+  );

--- a/frontend/digest/Digest.tsx
+++ b/frontend/digest/Digest.tsx
@@
+export function Digest({ userId }: { userId: string }) {
+  const { data } = useProfile(userId);
+  return (
+    <Layout>
+      <AxisTrendChart axes={data.axes} windows={data.windows} />
+      <section>
+        <h2>Recent work</h2>
+        {data.receipts.map(r => <ReceiptCard key={r.id} pr={r} />)}
+      </section>
+      <SummaryPanel text={data.weekly_summary} />
+    </Layout>
+  );
+}
--- a/frontend/digest/AxisTrendChart.tsx
+++ b/frontend/digest/AxisTrendChart.tsx
@@
+export function AxisTrendChart({ axes, windows }) {
+  return <LineChart data={toSeries(axes, windows)} xKey="window" yKeys={AXIS_KEYS} />;
+}
--- a/frontend/digest/ReceiptCard.tsx
+++ b/frontend/digest/ReceiptCard.tsx
@@
+export function ReceiptCard({ pr }) {
+  return (
+    <article className="receipt">
+      <Badge>{pr.ai_category}</Badge><Badge>{pr.ai_scope}</Badge>
+      <p>{pr.ai_impact_summary}</p>
+    </article>
+  );
+}
--- a/frontend/digest/__tests__/Digest.test.tsx
+++ b/frontend/digest/__tests__/Digest.test.tsx
@@
+test('renders one receipt per PR', () => {
+  render(<Digest userId="u1" />);
+  expect(screen.getAllByRole('article')).toHaveLength(3);
+});
